   "detect": "nonempty-contains",
   "contains": "Answer first (live-spec)",
   "note": "prints the chat-law reminder lines unconditionally on every UserPromptSubmit; a stub payload is enough to fire it"
  }
 },
 "cannot_red": {
  "register-judge-collect.sh": "Hands the turn's text to a background model call (register-judge.py, backgrounded with nohup) and returns immediately with exit 0 and empty stdout by design — the verdict lands asynchronously in a file for register-judge-report.sh to read and print on the human's next turn, so this half's own stdout can never carry a block decision for a fixture to catch; its sibling register-judge-report.sh is proven above instead."
 }
